import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */

const CATEGORIES = [
  {
    id: "All",
    label: "All",
    icon: Sparkles,
  },
  {
    id: "Rings",
    label: "Rings",
    icon: Gem,
  },
  {
    id: "Necklaces",
    label: "Necklaces",
    icon: Sparkles,
  },
  {
    id: "Bracelets",
    label: "Bracelets",
    icon: CircleDot,
  },
  {
    id: "Earrings",
    label: "Earrings",
    icon: Star,
  },
  {
    id: "Chains",
    label: "Chains",
    icon: Link2,
  },
  {
    id: "Watches",
    label: "Watches",
    icon: Watch,
  },
];

/* ============================================================
   PRODUCT DATA
   ============================================================ */

const PRODUCTS = [
  {
    id: 1,
    name: "Aria Solitaire Ring",
    category: "Rings",
    price: 189,
    icon: Gem,
    badge: "New",
    image: "/img/ring 1.jpeg",
  },

  {
    id: 2,
    name: "Verona Twist Band",
    category: "Rings",
    price: 145,
    icon: Gem,
    image: "/img/ring 2.jpeg",
  },

  {
    id: 3,
    name: "Celeste Starfish Ring",
    category: "Rings",
    price: 165,
    icon: Gem,
    image: "/img/ring 3.jpeg",
  },

  {
    id: 4,
    name: "Celeste Diamond Necklace",
    category: "Necklaces",
    price: 310,
    icon: Sparkles,
    badge: "Bestseller",
    image: "/img/chain 1.png",
  },

  {
    id: 5,
    name: "Noir Heart Necklace",
    category: "Necklaces",
    price: 175,
    icon: Sparkles,
    image: "/img/chain 2.png",
  },

  {
    id: 6,
    name: "Luna Moonstone Necklace",
    category: "Necklaces",
    price: 220,
    icon: Sparkles,
    badge: "New",
    image: "/img/chain 3.png",
  },

  {
    id: 7,
    name: "Olive Pearl Necklace",
    category: "Necklaces",
    price: 195,
    icon: Sparkles,
    image: "/img/chain 4.png",
  },

  {
    id: 8,
    name: "Stella Star Necklace",
    category: "Necklaces",
