/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {

  const Icon = product.icon;

  const [imgFailed, setImgFailed] = useState(false);

  const showImage =
    product.image &&
    !imgFailed;

  return (

    <article className="lux-card">

      <div className="lux-card-media">

        {showImage ? (

          <img
            src={product.image}
            alt={product.name}
            className="lux-card-img"
            loading="lazy"
            onError={() => setImgFailed(true)}
          />

        ) : (

          <div className="lux-card-media-icon">

            <Icon
              size={40}
              strokeWidth={1}
            />

          </div>

        )}

        {product.badge && (
          <span className="lux-card-badge">
            {product.badge}
          </span>
        )}

        <button
          className="lux-card-quickadd"
          aria-label={`Add ${product.name} to cart`}
        >

          <ShoppingBag
            size={16}
            strokeWidth={1.5}
          />

        </button>

      </div>

      <div className="lux-card-body">

        <span className="lux-card-eyebrow">
          {product.category}
        </span>

        <h3 className="lux-card-name">
          {product.name}
        </h3>

        <div className="lux-card-price">
          ${product.price.toFixed(2)}
        </div>

        <div className="lux-card-actions">

          <button className="lux-btn lux-btn-outline">
            View Details
          </button>

          <button className="lux-btn lux-btn-solid">
            Add to Cart
          </button>

        </div>

      </div>

    </article>

  );
}

/* ============================================================
   MAIN PAGE
   ============================================================ */

export default function CollectionsPage() {

  const [activeCategory, setActiveCategory] =
    useState("All");

  const filteredProducts = useMemo(() => {

    if (activeCategory === "All") {
      return PRODUCTS;
    }

    return PRODUCTS.filter(
      (product) =>
        product.category === activeCategory
    );

  }, [activeCategory]);

  return (

    <div className="lux-root">

      <style>{`

        ${fontImport}

      `}</style>

      {/* HERO */}

      <section className="lux-hero">

        <div className="lux-hero-eyebrow">
          The Full Edit
        </div>

        <h1>
          Our Collections
        </h1>

        <div className="lux-hero-divider">

          <span className="line" />

          <span className="diamond" />

          <span className="line" />

        </div>

        <p>
          Discover pieces designed to last a lifetime —
          rings, necklaces, bracelets, earrings, chains
          and watches, each finished by hand.
        </p>

      </section>

      {/* FILTERS */}

      <nav
        className="lux-filters"
        aria-label="Product categories"
      >

        {CATEGORIES.map(
          ({ id, label, icon: Icon }) => (

            <button
              key={id}
              className={`lux-filter-btn ${
                activeCategory === id
                  ? "is-active"
                  : ""
              }`}
              onClick={() =>
                setActiveCategory(id)
              }
            >

              <Icon
                size={14}
                strokeWidth={1.5}
              />

              {label}

            </button>

          )
        )}

      </nav>

      {/* PRODUCTS */}

      <section className="lux-grid-section">

        <div className="lux-grid-meta">

          <span>

            Showing{" "}

            <strong>
              {filteredProducts.length}
            </strong>{" "}

            {filteredProducts.length === 1
              ? "piece"
              : "pieces"}

          </span>

          <span>

            {activeCategory === "All"
              ? "All Collections"
              : activeCategory}

          </span>

        </div>

        {filteredProducts.length > 0 ? (

          <div className="lux-grid">

            {filteredProducts.map(
              (product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              )
            )}

          </div>

        ) : (

          <div className="lux-empty">

            No pieces found in this collection yet.

          </div>

        )}

      </section>

      {/* FOOTER */}

      <PlaceholderFooter />

    </div>

  );
}
